55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const BLOCK_SIZE = 3;
68	const BLOCK_BASE_PREMIUM = 60;
69	
70	const countByType = (items: Item[]): Map<string, number> => {
71	  const counts = new Map<string, number>();
72	  for (const item of items) {
73	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
74	  }
75	  return counts;
76	};
77	
78	const basePremiumOfGroup = (type: string, count: number): number =>
79	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
80	
81	const quote = (step: QuoteStep): QuoteResult => {
82	  const policyBase = [...countByType(step.items)].reduce(
83	    (total, [type, count]) => total + basePremiumOfGroup(type, count),
84	    0,
85	  );
86	  const premiumBeforeRounding =
87	    policyBase + policyBase * FIRST_INSURANCE_SURCHARGE_RATE + PROCESSING_FEE;
88	  return { premium: Math.ceil(premiumBeforeRounding) };
89	};
90	
91	export const runScenario = (scenario: Scenario): ScenarioOutput => {
92	  return { results: scenario.steps.map((step) => quote(step as QuoteStep)) };
93	};
