const policyBasePremium = (items: Item[]): number =>
  [...countByType(items)].reduce(
    (total, [type, count]) => total + basePremiumOfGroup(type, count),
    0,
  );

const firstInsuranceSurcharge = (policyBase: number): number =>
  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;

const quote = (step: QuoteStep): QuoteResult => {
  const policyBase = policyBasePremium(step.items);
  const premiumBeforeRounding =
    policyBase + firstInsuranceSurcharge(policyBase) + PROCESSING_FEE;
  return { premium: Math.ceil(premiumBeforeRounding) };
};

